    this.withdrawSurplusBeforeProjectEndRequestCreateUpdate.serviceProviderAgreementsId = this.contractorAgreementsId;
    this.withdrawSurplusBeforeProjectEndRequestCreateUpdate.contractorReportId = this.contractorReportId;
    this.withdrawSurplusBeforeProjectEndRequestCreateUpdate.financialReportId = this.financialReportId;
    this.withdrawSurplusBeforeProjectEndRequestCreateUpdate.letterOfCommitmentFromCharteredAccountantId = this.letterOfCommitmentFromCharteredAccountantId;
