      this.StudyDaysProgressSetting.percent = this.selectedRequest.licenseProjectRequestEventStatus.allowCustomerFeedbackRemainingStudyPeriod / this.selectedRequest.licenseProjectRequestEventStatus.allowCustomerFeedbackPeriod * 100;
      this.StudyDaysProgressSetting.title = this.selectedRequest.licenseProjectRequestEventStatus.allowCustomerFeedbackRemainingStudyPeriod.toString();
